static const char text_helpers [] =
	"# The standard library: small helpers for numbers and lists\n"
	"# mod (a, b): the remainder of a divided by b, with the sign of b: mod"
	" (-1, 5) is 4\n"
	"m:algebra mod(a, b) = a - b * floor(a / b)\n"
	"# sign (x): 1 for a positive x, -1 for a negative one, 0 for zero\n"
	"m:algebra sign(x) = if (x > 0, 1, if (x < 0, -1, 0))\n"
	"# frac (x): the part after the point, x less floor (x)\n"
	"m:algebra frac(x) = x - floor(x)\n"
	"# trunc (x): the whole part, cut toward zero\n"
	"m:algebra trunc(x) = sign(x) * floor(abs(x))\n"
	"# lerp (a, b, t): the point at the fraction t of the way from a to b\n"
	"m:algebra lerp(a, b, t) = a + (b - a) * t\n"
	"# clamp (x, lo, hi): x held between lo and hi\n"
	"m:algebra clamp(x, lo, hi) = max(lo, min(x, hi))\n"
	"# hypot (a, b): the length of the hypotenuse, sqrt (a^2 + b^2)\n"
	"m:algebra hypot(a, b) = sqrt(a^2 + b^2)\n"
	"# deg (r): radians to degrees\n"
	"m:algebra deg(r) = r * 180 / pi\n"
	"# rad (d): degrees to radians\n"
	"m:algebra rad(d) = d * pi / 180\n"
	"# linspace (a, b, n): n numbers from a to b, evenly spaced, both ends "
	"included\n"
	"m:algebra linspace(a, b, n) = map(k -> lerp(a, b, k / (n - 1)), range("
	"0, n - 1))\n"
	"# cumprod (xs): the running products of a list\n"
	"m:algebra cumprod(xs) = map(k -> prod(i, 1, k, xs[i]), range(1, len(xs"
	")))\n"
	"# dotl (xs, ys): the dot product of two lists of one length\n"
	"m:algebra dotl(xs, ys) = sum(i, 1, len(xs), xs[i] * ys[i])\n"
	"# normalize (xs): the list divided by its largest absolute value\n"
	"m:algebra normalize(xs) = xs / fold((m, x) -> max(m, abs(x)), 0, xs)\n";

static const char text_numbers [] =
	"# The standard library: number theory\n"
	"# fib (n): the n-th Fibonacci number, fib (0) = 0, fib (1) = 1; exact,"
	" also for big n\n"
	"m:algebra fib(n) = if (n < 2, n, _fib_from(n, 0, 1))\n"
	"m:algebra _fib_from(n, a, b) = if (n == 0, a, _fib_from(n - 1, b, a + "
	"b))\n"
	"# isqrt (n): the whole number part of the square root of a whole numbe"
	"r n, exact\n"
	"m:algebra isqrt(n) = if (n < 2, n, _isqrt(n, 1, n))\n"
	"m:algebra _isqrt(n, lo, hi) = if (hi - lo <= 1, lo, _isqrt_mid(n, lo, "
	"hi, floor((lo + hi) / 2)))\n"
	"m:algebra _isqrt_mid(n, lo, hi, m) = if (m * m <= n, _isqrt(n, m, hi),"
	" _isqrt(n, lo, m))\n"
	"# isprime (n): true when n is a prime; trial division, fast up to abou"
	"t 10^10\n"
	"m:algebra isprime(n) = if (n < 4, n > 1, len(filter(d -> mod(n, d) == "
	"0, range(2, isqrt(n)))) == 0)\n"
	"# primes (n): the primes up to n\n"
	"m:algebra primes(n) = if (n < 2, list(), filter(isprime, range(2, n)))\n"
	"# factor (n): the prime factors of n in order, factor (360) is [2, 2, "
	"2, 3, 3, 5]\n"
	"m:algebra factor(n) = if (n < 2, list(), _factor_step(n, _smallest_fac"
	"tor(n)))\n"
	"m:algebra _factor_step(n, p) = concat(list(p), factor(n / p))\n"
	"m:algebra _smallest_factor(n) = if (n < 4, n, _first_or(n, filter(d ->"
	" mod(n, d) == 0, range(2, isqrt(n)))))\n"
	"m:algebra _first_or(n, ds) = if (len(ds) == 0, n, item(ds, 1))\n"
	"# divisors (n): all the numbers that divide n, from 1 to n\n"
	"m:algebra divisors(n) = filter(d -> mod(n, d) == 0, range(1, n))\n"
	"# totient (n): how many of 1 ... n have no common factor with n\n"
	"m:algebra totient(n) = len(filter(k -> gcd(k, n) == 1, range(1, n)))\n"
	"# sigma (n): the sum of the divisors of n\n"
	"m:algebra sigma(n) = sum(divisors(n))\n"
	"# collatz (n): the steps of 3n + 1 (or n / 2 for an even n) until n re"
	"aches 1\n"
	"m:algebra collatz(n) = if (n == 1, 0, 1 + collatz(if (mod(n, 2) == 0, "
	"n / 2, 3 * n + 1)))\n"
	"# digits (n): the decimal digits of a whole number n, as a list\n"
	"m:algebra digits(n) = if (n < 10, list(n), append(digits(floor(n / 10)"
	"), mod(n, 10)))\n";

